98	      },
99	    },
100	
101	    // ── Visualização analítica ──
102	    notas_toggle_analytics: {
103	      id: 'notas_toggle_analytics',
104	      description: 'Alternar entre visão de lista e dashboard analítico de notas fiscais',
105	      execute: (data) => {
106	        const show = data?.show ?? true;
107	        setIsAnalyticsView(Boolean(show));
108	      },
109	    },
110	
111	    // ── Painel de upload ──
112	    notas_toggle_upload: {
113	      id: 'notas_toggle_upload',
