123	      const dateStr = invoice.data_nota || invoice.created_at;
124	      if (!dateStr) return false;
125	      const date = parseISO(dateStr);
126	      if (!isValid(date)) return false;
127	
128	      const from = dateRange.from as Date;
129	      const to = dateRange.to || dateRange.from || new Date();
130	
131	      const target = date.getTime();
132	      const startStr = new Date(from).setHours(0, 0, 0, 0);
133	      const endStr = new Date(to).setHours(23, 59, 59, 999);
134	
135	      return target >= startStr && target <= endStr;
136	    });
