152	
153	    const avgDailyVal = totalValue / daysDiff;
154	    const avgTicket = totalRecords > 0 ? totalValue / totalRecords : 0;
155	
156	    // Grouping Logic
157	    const isDailyGroup = daysDiff < 60;
158	
159	    const bySupplierValue: Record<string, number> = {};
160	    const supplierDisplayNames: Record<string, string> = {};
161	    const byCategoryValue: Record<string, number> = {};
162	    const byProductValue: Record<string, number> = {};
163	    const byCategoryProducts: Record<string, Record<string, { qtd: number; valor: number; fornecedores: Set<string> }>> = {};
164	    const byTime: Record<
165	      string,
166	      { date: string; value: number; count: number }
