137	/**
138	 * Detecta se os dados extraídos correspondem a uma NOTA DE TRANSFERÊNCIA
139	 * (ex: Momma Doces Saudáveis com itens em cx.) que NUNCA deve ser salva
140	 * como nota fiscal regular nem enviada ao financeiro.
141	 */
142	function isTransferNote(data: any): boolean {
143	  if (!data) return false;
144	  const fornecedor = (data.fornecedor || '')
145	    .toLowerCase()
146	    .normalize('NFD')
147	    .replace(/[\u0300-\u036f]/g, '');
148	  return (
149	    fornecedor.includes('momma doces') ||
150	    fornecedor.includes('doces saudaveis')
151	  );
152	}
